/**
 * Cloudflare Worker entry:
 *  - serves static build files (/_next/static, /flags, …) from Workers KV (see scripts/cf-upload-assets.mjs),
 *  - serves cached HTML of public pages to anonymous visitors (page cache, see below),
 *  - forwards everything else to the OpenNext-generated Next.js handler,
 *  - runs the business automations hourly through a Cron Trigger.
 */
// @ts-expect-error — generated by `opennextjs-cloudflare build`
import nextWorker from "./.open-next/worker.js";

type KV = {
  get(key: string, opts: { type: "text"; cacheTtl?: number }): Promise<string | null>;
  getWithMetadata(key: string, type: "arrayBuffer"): Promise<{ value: ArrayBuffer | null; metadata: { ct?: string } | null }>;
  put(key: string, value: string, opts?: { expirationTtl?: number }): Promise<void>;
};
type Env = { CRON_SECRET?: string; APP_URL?: string; STATIC_ASSETS?: KV; CF_VERSION_METADATA?: { id?: string }; [k: string]: unknown };
type Ctx = { waitUntil(p: Promise<unknown>): void };

const STATIC_PREFIXES = ["/_next/static/", "/flags/", "/brand/", "/images/"];

async function serveAsset(env: Env, pathname: string): Promise<Response | null> {
  if (!env.STATIC_ASSETS) return null;
  const { value, metadata } = await env.STATIC_ASSETS.getWithMetadata(decodeURIComponent(pathname), "arrayBuffer");
  if (!value) return null;
  const immutable = pathname.startsWith("/_next/static/");
  return new Response(value, {
    headers: {
      "Content-Type": metadata?.ct || "application/octet-stream",
      "Cache-Control": immutable ? "public, max-age=31536000, immutable" : "public, max-age=86400",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

// OpenNext may call env.ASSETS.fetch(); back it with the same KV store.
function withAssets(env: Env): Env {
  return {
    ...env,
    ASSETS: {
      fetch: async (input: Request | string) => {
        const url = new URL(typeof input === "string" ? input : input.url);
        return (await serveAsset(env, url.pathname)) ?? new Response("Not found", { status: 404 });
      },
    },
  };
}

/* ───────────────────────────── Page cache ─────────────────────────────
 * Every page is rendered on demand by Next.js, which costs CPU time on each visit. Public marketing pages are
 * identical for every anonymous visitor, so their HTML is stored in KV and served without running Next.js.
 *  - Only GET requests without query string, without a session cookie and without Next.js client-navigation
 *    headers are served from / stored in the cache. Logged-in users always get a fresh page.
 *  - Keys include the deployment version (a new deploy never serves old HTML) and a content version that is
 *    bumped whenever the admin area saves something (POST under /{locale}/admin), so edits show up at once.
 *  - Entries expire after PAGE_TTL so time-based content (banners, dates) refreshes on its own.
 */
const PAGE_TTL = 12 * 60 * 60;
const CONTENT_VERSION_KEY = "pagecache:content-version";
const CACHEABLE_PAGE = /^\/(fr|ar|en)(\/(visas|services|blog)(\/[a-z0-9-]+)?|\/legal\/[a-z0-9-]+|\/(pricing|faq|about|contact|track|credits))?\/?$/;
const ADMIN_PATH = /^\/(fr|ar|en)\/admin(\/|$)/;
const KEPT_HEADERS = [
  "content-type", "content-language", "content-security-policy", "x-frame-options", "x-content-type-options",
  "referrer-policy", "permissions-policy", "cross-origin-opener-policy", "strict-transport-security", "vary", "link",
];

function isCacheableRequest(request: Request, url: URL) {
  if (request.method !== "GET" || url.search) return false;
  if (!CACHEABLE_PAGE.test(url.pathname)) return false;
  const h = request.headers;
  if (h.get("rsc") || h.get("next-router-prefetch") || h.get("next-router-state-tree") || h.get("next-action")) return false;
  return !/(?:^|;\s*)va_session=/.test(h.get("cookie") || "");
}

async function pageKey(env: Env, kv: KV, pathname: string) {
  const content = (await kv.get(CONTENT_VERSION_KEY, { type: "text", cacheTtl: 60 })) || "0";
  const deploy = env.CF_VERSION_METADATA?.id || "dev";
  return `pagecache:${deploy}:${content}:${pathname.replace(/\/$/, "") || "/"}`;
}

async function cachedPage(request: Request, env: Env, ctx: Ctx, url: URL): Promise<Response> {
  const kv = env.STATIC_ASSETS!;
  const key = await pageKey(env, kv, url.pathname);
  const hit = await kv.get(key, { type: "text" });
  if (hit) {
    const nl = hit.indexOf("\n");
    const headers = new Headers(JSON.parse(hit.slice(0, nl)) as Record<string, string>);
    headers.set("x-page-cache", "HIT");
    return new Response(hit.slice(nl + 1), { status: 200, headers });
  }
  const res: Response = await nextWorker.fetch(request, withAssets(env), ctx);
  const type = res.headers.get("content-type") || "";
  if (res.status !== 200 || !type.startsWith("text/html") || res.headers.has("set-cookie")) return res;
  const body = await res.text();
  const kept: Record<string, string> = {};
  for (const name of KEPT_HEADERS) {
    const v = res.headers.get(name);
    if (v) kept[name] = v;
  }
  kept["cache-control"] = "private, no-cache";
  ctx.waitUntil(kv.put(key, `${JSON.stringify(kept)}\n${body}`, { expirationTtl: PAGE_TTL }).catch(() => {}));
  const headers = new Headers(res.headers);
  headers.set("x-page-cache", "MISS");
  return new Response(body, { status: 200, headers });
}

export default {
  async fetch(request: Request, env: Env, ctx: Ctx) {
    const url = new URL(request.url);
    const { pathname } = url;
    if ((request.method === "GET" || request.method === "HEAD") && STATIC_PREFIXES.some((p) => pathname.startsWith(p))) {
      const asset = await serveAsset(env, pathname);
      return asset ?? new Response("Not found", { status: 404 });
    }
    if (env.STATIC_ASSETS && isCacheableRequest(request, url)) {
      return cachedPage(request, env, ctx, url);
    }
    const res: Response = await nextWorker.fetch(request, withAssets(env), ctx);
    // Something was saved in the admin area: start a new page-cache generation.
    if (request.method === "POST" && ADMIN_PATH.test(pathname) && res.status < 400 && env.STATIC_ASSETS) {
      ctx.waitUntil(env.STATIC_ASSETS.put(CONTENT_VERSION_KEY, String(Date.now())).catch(() => {}));
    }
    return res;
  },

  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    const base = (env.APP_URL || "https://localhost").replace(/\/$/, "");
    const req = new Request(`${base}/api/cron/run`, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(
      nextWorker.fetch(req, withAssets(env), ctx).then(async (res: Response) => {
        if (!res.ok) console.error("[cron] automation run failed", res.status, await res.text());
      }),
    );
  },
};
